// Reusable UI tests (generated by engineering-platform frontend-enterprise-management asset)
import { describe, it, expect } from 'vitest';
import { mount } from '@vue/test-utils';
import AppTable from '../src/components/AppTable.vue';
import AppForm from '../src/components/AppForm.vue';
import StatusTag from '../src/components/StatusTag.vue';
import ConfirmAction from '../src/components/ConfirmAction.vue';

const epStubs = {
  'el-table': true, 'el-table-column': true, 'el-pagination': true, 'el-tag': true,
  'el-button': true, 'el-icon': true, 'el-dropdown': true, 'el-dropdown-menu': true,
  'el-dropdown-item': true, 'el-form': true, 'el-form-item': true, 'el-alert': true,
  'el-popconfirm': true, 'el-skeleton': true, 'el-empty': true, 'el-result': true,
};

// stubs that render slot content (so component text/actions remain testable)
const withSlots = { template: '<div><slot /></div>' };

describe('AppTable', () => {
  it('renders loading state without data', () => {
    const wrapper = mount(AppTable, {
      props: { loading: true, data: [], total: 0, page: 1, size: 20 },
      global: { stubs: epStubs },
    });
    expect(wrapper.find('[data-testid="app-table"]').exists()).toBe(true);
  });

  it('shows error state with retry that emits refresh', async () => {
    const wrapper = mount(AppTable, {
      props: { error: 'boom', data: [], total: 0, page: 1, size: 20 },
      global: { stubs: epStubs },
    });
    expect(wrapper.find('[data-testid="app-table-error"]').exists()).toBe(true);
    // Retry button is an el-button stub: emit via its click handler
    const retry = wrapper.find('[data-testid="app-table-error"] button');
    if (retry.exists()) {
      await retry.trigger('click');
    } else {
      wrapper.findComponent({ name: 'ElButton' }).vm.$emit('click');
    }
    expect(wrapper.emitted('refresh')).toBeTruthy();
  });

  it('shows pagination when total > 0', () => {
    const wrapper = mount(AppTable, {
      props: { data: [{ id: '1'}], total: 30, page: 1, size: 20 },
      global: { stubs: epStubs },
    });
    expect(wrapper.find('.data-card-pagination').exists()).toBe(true);
  });
});

describe('StatusTag', () => {
  it('maps enabled to success pill with Enabled label', () => {
    const wrapper = mount(StatusTag, { props: { enabled: true }, global: { stubs: epStubs } });
    const tag = wrapper.find('[data-testid="status-tag"]');
    expect(tag.exists()).toBe(true);
    expect(tag.classes()).toContain('is-enabled');
    expect(tag.text()).toContain('Enabled');
  });
  it('maps disabled to muted pill with Disabled label', () => {
    const wrapper = mount(StatusTag, { props: { enabled: false }, global: { stubs: epStubs } });
    const tag = wrapper.find('[data-testid="status-tag"]');
    expect(tag.exists()).toBe(true);
    expect(tag.classes()).toContain('is-disabled');
    expect(tag.text()).toContain('Disabled');
  });
});

describe('ConfirmAction', () => {
  it('emits confirm on popconfirm confirm', () => {
    const wrapper = mount(ConfirmAction, {
      props: { title: 'Disable?' },
      slots: { default: '<button>Disable</button>' },
      global: { stubs: epStubs },
    });
    wrapper.findComponent({ name: 'ElPopconfirm' }).vm.$emit('confirm');
    expect(wrapper.emitted('confirm')).toBeTruthy();
  });
});

describe('AppForm', () => {
  it('emits submit and cancel', async () => {
    const wrapper = mount(AppForm, {
      props: { model: { name: 'x' } },
      global: { stubs: { ...epStubs, 'el-form': withSlots, 'el-button': withSlots } },
    });
    // form stub has no validate -> submit fires directly
    await wrapper.find('[data-testid="app-form-submit"]').trigger('click');
    expect(wrapper.emitted('submit')).toBeTruthy();
    // cancel button is the first el-button stub in footer
    const buttons = wrapper.findAll('.app-form-footer .el-button-stub');
    if (buttons.length > 0) {
      await buttons[0].trigger('click');
    } else {
      wrapper.find('.app-form-footer').findAll('*')[0].trigger('click');
    }
    expect(wrapper.emitted('cancel')).toBeTruthy();
  });

  it('shows error alert when error prop set', () => {
    const wrapper = mount(AppForm, {
      props: { model: {}, error: 'USERNAME_DUPLICATE: taken' },
      global: { stubs: epStubs },
    });
    expect(wrapper.find('[data-testid="app-form-error"]').exists()).toBe(true);
  });
});
